-- Laboratório v4 (20/10/2026, ESPEC-LABORATORIO-v4.md): nós do funil de verdade, mensagens e criativos,
-- categoria na galeria de templates e 25 templates oficiais novos.
--
-- Contrato: Aceleriq-Laboratorio/ESPEC-LABORATORIO-v4.md (seções 2 e 3). Função: supabase/functions/laboratorio
-- (modulos/regras.ts, modulos/templates.ts e nos-v4.ts).
--
-- 1) lab_templates ganha a coluna categoria (Funis, Lançamento, Criativos, UGC e influência, Marca, Sites,
--    Mensagens, Webinar, Quiz); os 13 oficiais de antes recebem a categoria. Template salvo pela equipe
--    fica sem categoria (a galeria mostra em "Outros").
-- 2) lab_execucoes.tipo aceita os 22 nós novos (marca, cliente, referencias, video, arquivo, produto, pagina,
--    checkout, quiz, webinar, dominio, teste_ab, automacao, email, whatsapp, area_membros, ugc,
--    influenciador, template_designer, crm, recuperacao, fontes_trafego).
-- 3) Semente: os 25 templates oficiais da v4 (TEMPLATES_OFICIAIS_V4), com o gatilho no fio (ligacoes[].gatilho).
--
-- O gatilho da ligação e as saídas dos nós novos moram em lab_projetos.canvas e lab_execucoes.saida (jsonb):
-- não mudam o banco. Mensagens saem como rascunho; nada é enviado sem a aprovação do dono (Pôr no ar).
--
-- Idempotente e só amplia. Nada é apagado.

-- ─── 1) Categoria dos templates ─────────────────────────────────────────────
ALTER TABLE public.lab_templates ADD COLUMN IF NOT EXISTS categoria text;
ALTER TABLE public.lab_templates DROP CONSTRAINT IF EXISTS lab_templates_categoria_tamanho;
ALTER TABLE public.lab_templates ADD CONSTRAINT lab_templates_categoria_tamanho CHECK (categoria IS NULL OR char_length(categoria) BETWEEN 1 AND 60);

UPDATE public.lab_templates SET categoria = 'Criativos' WHERE oficial AND id IN ('6c0a1b10-0000-4000-8000-000000000001'::uuid, '6c0a1b10-0000-4000-8000-000000000002'::uuid, '6c0a1b10-0000-4000-8000-000000000005'::uuid, '6c0a1b10-0000-4000-8000-000000000006'::uuid, '6c0a1b10-0000-4000-8000-00000000000a'::uuid);
UPDATE public.lab_templates SET categoria = 'Marca' WHERE oficial AND id IN ('6c0a1b10-0000-4000-8000-000000000003'::uuid, '6c0a1b10-0000-4000-8000-000000000009'::uuid);
UPDATE public.lab_templates SET categoria = 'Sites' WHERE oficial AND id IN ('6c0a1b10-0000-4000-8000-000000000004'::uuid);
UPDATE public.lab_templates SET categoria = 'Funis' WHERE oficial AND id IN ('6c0a1b10-0000-4000-8000-000000000007'::uuid, '6c0a1b10-0000-4000-8000-000000000008'::uuid, '6c0a1b10-0000-4000-8000-00000000000b'::uuid);
UPDATE public.lab_templates SET categoria = 'Lançamento' WHERE oficial AND id IN ('6c0a1b10-0000-4000-8000-00000000000c'::uuid);
UPDATE public.lab_templates SET categoria = 'Webinar' WHERE oficial AND id IN ('6c0a1b10-0000-4000-8000-00000000000d'::uuid);

-- ─── 2) Tipos de nó das execuções ───────────────────────────────────────────
ALTER TABLE public.lab_execucoes DROP CONSTRAINT IF EXISTS lab_execucoes_tipo_check;
ALTER TABLE public.lab_execucoes
  ADD CONSTRAINT lab_execucoes_tipo_check CHECK (tipo IN ('contexto', 'midia', 'config', 'gravity', 'agente', 'copy', 'imagem', 'carrossel', 'logo', 'landing', 'anuncio', 'agente_externo', 'pesquisa', 'oferta', 'funil', 'filme', 'por_no_ar', 'avatar', 'order_bump', 'upsell', 'downsell', 'sequencia_ofertas', 'secoes_pagina', 'sequencia_mensagens', 'refino_tom', 'marca', 'cliente', 'referencias', 'video', 'arquivo', 'produto', 'pagina', 'checkout', 'quiz', 'webinar', 'dominio', 'teste_ab', 'automacao', 'email', 'whatsapp', 'area_membros', 'ugc', 'influenciador', 'template_designer', 'crm', 'recuperacao', 'fontes_trafego'));

-- ─── 3) Semente: os 25 templates oficiais da v4 ─────────────────────────────
